<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { Head } from '@inertiajs/vue3';
import ErpLayout from '@/layouts/ErpLayout.vue';
import Icon from '@/components/dashboard/Icon.vue';

const props = withDefaults(defineProps<{ userName?: string; userEmail?: string; initialTab?: 'promotions' | 'flash' }>(), { userName: '', userEmail: '', initialTab: 'promotions' });
type Promotion = { id:number; name:string; code:string|null; discount_type:'percent'|'fixed'; discount_value:string|number; scope:string; status:string; starts_at:string|null; ends_at:string|null; usage_count:number; usage_limit:number|null; priority:number; product?:{name:string}|null; variant?:{name:string;sku:string}|null; category?:{name:string}|null };
type FlashItem = { id?:number; product_variant_id:number; regular_price:number|string; sale_price:number|string; quantity_limit:number|null; quantity_sold?:number; variant?:{name:string;sku:string;product?:{name:string}} };
type FlashSale = { id:number; title:string; slug:string; tagline:string|null; status:string; starts_at:string; ends_at:string; show_on_storefront:boolean; priority:number; items:FlashItem[] };
type Option = {id:number;name:string;sku?:string|null;selling_price?:number|string;wholesale_price?:number|string|null;product?:{name:string}};
const headers=()=>({Accept:'application/json','Content-Type':'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.getAttribute('content')??''});
const tab=ref<'promotions'|'flash'>(props.initialTab), loading=ref(false), saving=ref(false), search=ref(''), statusFilter=ref('all'), notice=ref(''), noticeType=ref<'success'|'error'>('success');
const promotions=ref<Promotion[]>([]), sales=ref<FlashSale[]>([]), products=ref<any[]>([]), categories=ref<any[]>([]), variants=ref<Option[]>([]);
const promotionStats=ref({total:0,active:0,scheduled:0,codes:0}), flashStats=ref({total:0,live:0,scheduled:0,products:0});
const promoModal=ref(false), flashModal=ref(false), promoEdit=ref<Promotion|null>(null), flashEdit=ref<FlashSale|null>(null);
const promo=reactive({name:'',code:'',description:'',discount_type:'percent',discount_value:10,scope:'order',product_id:null as number|null,product_variant_id:null as number|null,product_category_id:null as number|null,minimum_order_amount:0,minimum_quantity:1,usage_limit:null as number|null,per_customer_limit:null as number|null,priority:100,stackable:false,publicly_visible:true,status:'draft',starts_at:'',ends_at:''});
const flash=reactive({title:'',slug:'',tagline:'',description:'',status:'draft',banner_image:'',accent_color:'#059669',starts_at:'',ends_at:'',show_on_storefront:true,priority:100,items:[{product_variant_id:0,regular_price:0,sale_price:0,quantity_limit:null as number|null,sort_order:0}]});
const stats=computed(()=>tab.value==='promotions'?promotionStats.value:{total:flashStats.value.total,active:flashStats.value.live,scheduled:flashStats.value.scheduled,codes:flashStats.value.products});
function notify(s:string,type:'success'|'error'='success'){notice.value=s;noticeType.value=type;window.setTimeout(()=>{if(notice.value===s)notice.value='';},4000);}
async function call(url:string,method='GET',body?:unknown){const r=await fetch(url,{method,credentials:'same-origin',headers:headers(),...(body?{body:JSON.stringify(body)}:{})});const p=await r.json().catch(()=>({}));if(!r.ok)throw new Error(p.message??Object.values(p.errors??{}).flat()[0]??'Request failed.');return p;}
async function load(){loading.value=true;try{const qs=new URLSearchParams({search:search.value,status:statusFilter.value,per_page:'50'});const p=await call(`/api/pricing/promotions?${qs}`);promotions.value=p.data??[];promotionStats.value=p.stats??promotionStats.value;const f=await call(`/api/pricing/flash-sales?${qs}`);sales.value=f.data??[];flashStats.value=f.stats??flashStats.value;}catch(e){notify(e instanceof Error?e.message:'Could not load pricing data.','error');}finally{loading.value=false;}}
async function loadOptions(){try{const p=await call('/api/pricing/options');products.value=p.products??[];categories.value=p.categories??[];variants.value=(p.variants??[]).map((v:Option)=>({...v,label:`${v.product?.name??'Product'} · ${v.name||'Standard'} · ${v.sku||'No SKU'}`}));}catch(e){notify(e instanceof Error?e.message:'Could not load product options.','error');}}
function resetPromo(){promoEdit.value=null;Object.assign(promo,{name:'',code:'',description:'',discount_type:'percent',discount_value:10,scope:'order',product_id:null,product_variant_id:null,product_category_id:null,minimum_order_amount:0,minimum_quantity:1,usage_limit:null,per_customer_limit:null,priority:100,stackable:false,publicly_visible:true,status:'draft',starts_at:'',ends_at:''});promoModal.value=true;}
function editPromo(p:Promotion){promoEdit.value=p;Object.assign(promo,{...p,description:(p as any).description??'',starts_at:p.starts_at?.slice(0,16)??'',ends_at:p.ends_at?.slice(0,16)??'',product_id:(p as any).product_id??null,product_variant_id:(p as any).product_variant_id??null,product_category_id:(p as any).product_category_id??null,minimum_order_amount:(p as any).minimum_order_amount??0,minimum_quantity:(p as any).minimum_quantity??1,usage_limit:p.usage_limit??null,per_customer_limit:(p as any).per_customer_limit??null,priority:(p as any).priority??100,stackable:(p as any).stackable??false,publicly_visible:(p as any).publicly_visible??true});promoModal.value=true;}
async function savePromo(){saving.value=true;try{const payload={...promo,code:promo.code||null,starts_at:promo.starts_at||null,ends_at:promo.ends_at||null};await call(promoEdit.value?`/api/pricing/promotions/${promoEdit.value.id}`:'/api/pricing/promotions',promoEdit.value?'PUT':'POST',payload);promoModal.value=false;notify('Promotion saved successfully.');await load();}catch(e){notify(e instanceof Error?e.message:'Could not save promotion.','error');}finally{saving.value=false;}}
function resetFlash(){flashEdit.value=null;Object.assign(flash,{title:'',slug:'',tagline:'',description:'',status:'draft',banner_image:'',accent_color:'#059669',starts_at:'',ends_at:'',show_on_storefront:true,priority:100,items:[{product_variant_id:0,regular_price:0,sale_price:0,quantity_limit:null,sort_order:0}]});flashModal.value=true;}
function editFlash(s:FlashSale){flashEdit.value=s;Object.assign(flash,{...s,starts_at:s.starts_at?.slice(0,16)??'',ends_at:s.ends_at?.slice(0,16)??'',items:s.items.map(i=>({product_variant_id:i.product_variant_id,regular_price:Number(i.regular_price),sale_price:Number(i.sale_price),quantity_limit:i.quantity_limit,sort_order:0}))});if(!flash.items.length)flash.items=[{product_variant_id:0,regular_price:0,sale_price:0,quantity_limit:null,sort_order:0}];flashModal.value=true;}
function addFlashItem(){flash.items.push({product_variant_id:0,regular_price:0,sale_price:0,quantity_limit:null,sort_order:flash.items.length});}
async function saveFlash(){saving.value=true;try{await call(flashEdit.value?`/api/pricing/flash-sales/${flashEdit.value.id}`:'/api/pricing/flash-sales',flashEdit.value?'PUT':'POST',{...flash,starts_at:flash.starts_at,ends_at:flash.ends_at,items:flash.items.filter(i=>i.product_variant_id)});flashModal.value=false;notify('Flash sale saved successfully.');await load();}catch(e){notify(e instanceof Error?e.message:'Could not save flash sale.','error');}finally{saving.value=false;}}
async function remove(kind:'promotions'|'flash-sales',id:number){if(!window.confirm('Delete this record? This cannot be undone.'))return;try{await call(`/api/pricing/${kind}/${id}`,'DELETE');notify('Record deleted.');await load();}catch(e){notify(e instanceof Error?e.message:'Could not delete record.','error');}}
function money(n:number|string){return new Intl.NumberFormat('en-BD',{style:'currency',currency:'BDT',maximumFractionDigits:2}).format(Number(n)||0);}
function pretty(s:string){return s.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());}
watch([tab,search,statusFilter],()=>load());
onMounted(()=>{loadOptions();load();});
</script>

<template>
<Head title="Pricing & Promotions" />
<ErpLayout :user-name="props.userName" :user-email="props.userEmail">
  <div class="pricing-page">
    <header class="pricing-hero">
      <div class="pricing-hero-main">
        <nav class="pricing-breadcrumb" aria-label="Breadcrumb">
          <a href="/dashboard">Workspace</a>
          <Icon name="chevron-right" :size="13" />
          <strong>Pricing & Promotions</strong>
        </nav>
        <div class="pricing-title">
          <span class="pricing-title-icon"><Icon name="tag" :size="22" /></span>
          <div>
            <h1>Pricing & Promotions</h1>
            <p>Manage pricing rules, promotional offers and time-bound flash campaigns.</p>
          </div>
        </div>
      </div>
      <div class="head-actions">
        <a class="btn soft" href="/shop/flash-sales" target="_blank" rel="noreferrer"><Icon name="external-link" :size="16"/> Storefront preview</a>
        <button class="btn primary" @click="tab==='promotions'?resetPromo():resetFlash()"><Icon name="plus" :size="16"/>{{tab==='promotions'?'Create promotion':'Create flash sale'}}</button>
      </div>
    </header>
    <div v-if="notice" class="notice" :class="noticeType">{{notice}}</div>
    <div class="tabs"><button :class="{active:tab==='promotions'}" @click="tab='promotions'"><Icon name="tag" :size="16"/> Promotions</button><button :class="{active:tab==='flash'}" @click="tab='flash'"><Icon name="zap" :size="16"/> Flash sales</button></div>
    <div class="stats"><article><span>Total {{tab==='promotions'?'promotions':'flash sales'}}</span><strong>{{stats.total}}</strong><small>All records</small></article><article><span>Active</span><strong>{{stats.active}}</strong><small>Currently enabled</small></article><article><span>Scheduled</span><strong>{{stats.scheduled}}</strong><small>Starts in the future</small></article><article><span>{{tab==='promotions'?'Coupon codes':'Sale products'}}</span><strong>{{stats.codes}}</strong><small>{{tab==='promotions'?'Promotions with a code':'Products in campaigns'}}</small></article></div>
    <section class="directory"><header class="directory-head"><div><h2>{{tab==='promotions'?'Promotion rules':'Flash sale campaigns'}}</h2><p>{{tab==='promotions'?'Define discount logic, eligibility and campaign windows.':'Schedule storefront campaigns with item-level sale pricing and stock limits.'}}</p></div><div class="filters"><label class="search"><Icon name="search" :size="16"/><input v-model="search" placeholder="Search name or code…"/></label><select v-model="statusFilter"><option value="all">All statuses</option><option v-for="s in ['draft','active','paused','ended']" :key="s" :value="s">{{pretty(s)}}</option></select><button class="btn ghost" @click="load"><Icon name="refresh-cw" :size="15"/> Refresh</button></div></header>
      <div v-if="loading" class="empty">Loading pricing data…</div>
      <div v-else-if="tab==='promotions' && promotions.length" class="table-wrap"><table><thead><tr><th>Promotion</th><th>Discount</th><th>Scope</th><th>Schedule</th><th>Priority</th><th>Usage</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="p in promotions" :key="p.id"><td><strong>{{p.name}}</strong><small>{{p.code||'No coupon code'}}</small></td><td><strong>{{p.discount_type==='percent'?`${p.discount_value}%`:money(p.discount_value)}}</strong></td><td>{{pretty(p.scope)}}<small>{{p.variant?.sku||p.product?.name||p.category?.name||'Cart-wide rule'}}</small></td><td>{{p.starts_at?new Date(p.starts_at).toLocaleDateString():'No start'}}<small>Until {{p.ends_at?new Date(p.ends_at).toLocaleDateString():'indefinite'}}</small></td><td>{{p.priority??100}}</td><td>{{p.usage_count}} / {{p.usage_limit??'∞'}}</td><td><span class="status" :class="p.status">{{pretty(p.status)}}</span></td><td class="actions"><button class="icon-btn" title="Edit" @click="editPromo(p)"><Icon name="pencil" :size="16"/></button><button class="icon-btn danger" title="Delete" @click="remove('promotions',p.id)"><Icon name="trash-2" :size="16"/></button></td></tr></tbody></table></div>
      <div v-else-if="tab==='flash' && sales.length" class="table-wrap"><table><thead><tr><th>Campaign</th><th>Products</th><th>Schedule</th><th>Storefront</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="s in sales" :key="s.id"><td><strong>{{s.title}}</strong><small>/shop/flash-sales · {{s.slug}}</small></td><td>{{s.items.length}} products</td><td>{{new Date(s.starts_at).toLocaleString()}}<small>Until {{new Date(s.ends_at).toLocaleString()}}</small></td><td><span class="status" :class="s.show_on_storefront?'active':'paused'">{{s.show_on_storefront?'Visible':'Hidden'}}</span></td><td><span class="status" :class="s.status">{{pretty(s.status)}}</span></td><td class="actions"><button class="icon-btn" title="Edit" @click="editFlash(s)"><Icon name="pencil" :size="16"/></button><button class="icon-btn danger" title="Delete" @click="remove('flash-sales',s.id)"><Icon name="trash-2" :size="16"/></button></td></tr></tbody></table></div>
      <div v-else class="empty"><span class="empty-icon"><Icon name="layers" :size="22"/></span><strong>No {{tab==='promotions'?'promotions':'flash sales'}} found</strong><p>Create your first record to start managing commercial offers.</p><button class="btn primary" @click="tab==='promotions'?resetPromo():resetFlash()"><Icon name="plus" :size="15"/> Create {{tab==='promotions'?'promotion':'flash sale'}}</button></div>
    </section>
  </div>
  <div v-if="promoModal" class="overlay" @click.self="promoModal=false"><section class="modal"><header><div><span class="eyebrow">PRICING RULE</span><h2>{{promoEdit?'Edit promotion':'Create promotion'}}</h2></div><button class="icon-btn" @click="promoModal=false"><Icon name="x" :size="18"/></button></header><form @submit.prevent="savePromo"><div class="form-grid"><label class="wide">Promotion name<input v-model="promo.name" required maxlength="160"/></label><label>Coupon code<input v-model="promo.code" placeholder="Optional; e.g. WHOLESALE10"/></label><label>Status<select v-model="promo.status"><option v-for="s in ['draft','active','paused','ended']" :key="s" :value="s">{{pretty(s)}}</option></select></label><label>Discount type<select v-model="promo.discount_type"><option value="percent">Percentage</option><option value="fixed">Fixed amount (BDT)</option></select></label><label>Discount value<input v-model.number="promo.discount_value" type="number" min="0.01" :max="promo.discount_type==='percent'?100:100000000" step="0.01" required/></label><label>Applies to<select v-model="promo.scope"><option value="order">Entire order</option><option value="product">Product</option><option value="variant">Variant</option><option value="category">Category</option></select></label><label v-if="promo.scope==='product'">Product<select v-model="promo.product_id" required><option :value="null">Choose product</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label v-if="promo.scope==='variant'">Variant<select v-model="promo.product_variant_id" required><option :value="null">Choose variant</option><option v-for="v in variants" :key="v.id" :value="v.id">{{(v as any).label}}</option></select></label><label v-if="promo.scope==='category'">Category<select v-model="promo.product_category_id" required><option :value="null">Choose category</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Minimum order (BDT)<input v-model.number="promo.minimum_order_amount" type="number" min="0" step="0.01"/></label><label>Minimum quantity<input v-model.number="promo.minimum_quantity" type="number" min="0.001" step="0.001"/></label><label>Usage limit<input v-model.number="promo.usage_limit" type="number" min="1" placeholder="Unlimited"/></label><label>Per-customer limit<input v-model.number="promo.per_customer_limit" type="number" min="1" placeholder="Unlimited"/></label><label>Priority (lower runs first)<input v-model.number="promo.priority" type="number" min="0" max="100000" step="1"/></label><label>Starts at<input v-model="promo.starts_at" type="datetime-local"/></label><label>Ends at<input v-model="promo.ends_at" type="datetime-local"/></label><label class="check"><input v-model="promo.stackable" type="checkbox"/> Can stack with other promotions</label><label class="check"><input v-model="promo.publicly_visible" type="checkbox"/> Show publicly on storefront</label><label class="wide">Description<textarea v-model="promo.description" rows="2"/></label></div><footer><button type="button" class="btn ghost" @click="promoModal=false">Cancel</button><button class="btn primary" :disabled="saving">{{saving?'Saving…':'Save promotion'}}</button></footer></form></section></div>
  <div v-if="flashModal" class="overlay" @click.self="flashModal=false"><section class="modal large"><header><div><span class="eyebrow">LIMITED-TIME CAMPAIGN</span><h2>{{flashEdit?'Edit flash sale':'Create flash sale'}}</h2></div><button class="icon-btn" @click="flashModal=false"><Icon name="x" :size="18"/></button></header><form @submit.prevent="saveFlash"><div class="form-grid"><label>Campaign title<input v-model="flash.title" required maxlength="160"/></label><label>Slug<input v-model="flash.slug" placeholder="Auto-generated if empty"/></label><label class="wide">Tagline<input v-model="flash.tagline" placeholder="A short storefront headline"/></label><label>Status<select v-model="flash.status"><option v-for="s in ['draft','active','paused','ended']" :key="s" :value="s">{{pretty(s)}}</option></select></label><label>Accent color<input v-model="flash.accent_color" type="color"/></label><label>Starts at<input v-model="flash.starts_at" type="datetime-local" required/></label><label>Ends at<input v-model="flash.ends_at" type="datetime-local" required/></label><label>Priority (lower first)<input v-model.number="flash.priority" type="number" min="0"/></label><label>Banner image URL<input v-model="flash.banner_image" type="url" placeholder="Optional https://…"/></label><label class="check"><input v-model="flash.show_on_storefront" type="checkbox"/> Publish on storefront while live</label><label class="wide">Description<textarea v-model="flash.description" rows="2"/></label></div><div class="items-head"><h3>Flash sale products</h3><button type="button" class="btn soft" @click="addFlashItem"><Icon name="plus" :size="15"/> Add product</button></div><div v-for="(item,i) in flash.items" :key="i" class="item-row"><label>Variant<select v-model.number="item.product_variant_id" required @change="()=>{const v=variants.find(v=>v.id===item.product_variant_id);if(v){item.regular_price=Number(v.selling_price)||0;if(!item.sale_price)item.sale_price=Math.max(0,item.regular_price*0.9)}}"><option :value="0">Choose variant</option><option v-for="v in variants" :key="v.id" :value="v.id">{{(v as any).label}}</option></select></label><label>Regular price<input v-model.number="item.regular_price" type="number" min="0.01" step="0.01" required/></label><label>Sale price<input v-model.number="item.sale_price" type="number" min="0.01" step="0.01" required/></label><label>Stock cap<input v-model.number="item.quantity_limit" type="number" min="1" placeholder="Unlimited"/></label><button v-if="flash.items.length>1" type="button" class="icon-btn danger" @click="flash.items.splice(i,1)"><Icon name="trash-2" :size="16"/></button></div><footer><button type="button" class="btn ghost" @click="flashModal=false">Cancel</button><button class="btn primary" :disabled="saving">{{saving?'Saving…':'Save flash sale'}}</button></footer></form></section></div>
</ErpLayout>
</template>

<style scoped>
.pricing-page{width:100%;max-width:none;margin:0;padding:0;display:grid;gap:16px;color:var(--foreground,#172033);box-sizing:border-box}
.pricing-hero{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;flex-wrap:wrap}
.pricing-hero-main{min-width:0}
