.tabs button{display:flex;align-items:center;gap:7px;background:transparent;border:0;border-bottom:2px solid transparent;padding:10px 13px;color:#64748b;font-size:12px;font-weight:650;cursor:pointer;transition:color .15s,background .15s}
.tabs button:hover{color:#047857;background:#f0fdf4}.tabs button.active{color:#047857;border-color:#059669;background:#ecfdf5;border-radius:8px 8px 0 0}
.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.stats article,.directory{background:#fff;border:1px solid #e5eaf0;border-radius:14px;box-shadow:0 1px 3px #0f172a05}
.stats article{padding:14px;display:grid;gap:5px}.stats span{color:#718096;font-size:11px}.stats strong{font-size:23px;line-height:1.2;font-weight:750;letter-spacing:-.025em}.stats small,.table-wrap small{display:block;color:#94a3b8;font-size:10px;margin-top:3px}
.directory{padding:15px}.directory-head{display:flex;align-items:center;justify-content:space-between;gap:14px;padding-bottom:13px;border-bottom:1px solid #edf1f5}.directory-head h2{font-size:14px;margin:0 0 4px;font-weight:700;letter-spacing:-.01em}.filters{justify-content:flex-end}
.search{display:flex;align-items:center;gap:7px;border:1px solid #dbe3eb;border-radius:9px;padding:0 9px;color:#94a3b8;background:#fff}.search:focus-within{border-color:#6ee7b7;box-shadow:0 0 0 3px #ecfdf5}.search input{height:35px;width:190px;border:0;outline:0;font-size:11px;background:transparent;color:#334155}
.filters select,.form-grid input,.form-grid select,.form-grid textarea,.item-row input,.item-row select{border:1px solid #dbe3eb;border-radius:9px;background:#fff;padding:8px 9px;font:inherit;font-size:11px;min-width:0;color:#334155}.filters select{height:37px;color:#475569}
.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:11px}th{text-align:left;background:#f8fafc;color:#64748b;font-size:9px;letter-spacing:.045em;font-weight:700;padding:10px 9px}td{padding:11px 9px;border-bottom:1px solid #edf1f5;white-space:nowrap}td strong{font-size:11px}
.status{display:inline-flex;border-radius:6px;padding:4px 7px;font-size:9px;font-weight:700;background:#f1f5f9;color:#64748b}.status.active{background:#dcfce7;color:#047857}.status.paused{background:#fff7ed;color:#c2410c}.status.ended{background:#f1f5f9;color:#64748b}.status.draft{background:#eff6ff;color:#1d4ed8}
.actions{display:flex;gap:5px}.icon-btn{display:inline-grid;place-items:center;width:30px;height:30px;border:1px solid #dbe3eb;border-radius:8px;background:#fff;color:#64748b;cursor:pointer}.icon-btn:hover{border-color:#6ee7b7;color:#047857;background:#f0fdf4}.icon-btn.danger:hover{color:#dc2626;border-color:#fecaca;background:#fef2f2}
.empty{min-height:165px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;color:#64748b;font-size:11px}.empty strong{color:#0f172a;font-size:13px}.empty p{margin:0 0 5px}.empty-icon{display:grid;place-items:center;background:#ecfdf5;color:#059669;width:40px;height:40px;border-radius:12px}
.notice{border-radius:9px;padding:9px 12px;font-size:11px}.notice.success{background:#ecfdf5;color:#047857}.notice.error{background:#fef2f2;color:#b91c1c}
.overlay{position:fixed;inset:0;background:#0f172a80;z-index:1000;display:flex;align-items:center;justify-content:center;padding:16px}.modal{background:#fff;width:min(760px,100%);max-height:92vh;overflow:auto;border-radius:16px;padding:20px;box-shadow:0 24px 70px #0f172a40}.modal.large{width:min(960px,100%)}.modal>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.modal h2{font-size:18px;margin:4px 0}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.form-grid label,.item-row label{display:grid;gap:5px;color:#475569;font-size:10px;font-weight:650}.form-grid .wide{grid-column:1/-1}.form-grid .check{display:flex;align-items:center;gap:8px}.form-grid .check input{min-width:auto}.modal footer{display:flex;justify-content:flex-end;gap:8px;margin-top:18px;padding-top:13px;border-top:1px solid #edf1f5}.items-head{display:flex;justify-content:space-between;align-items:center;margin:17px 0 9px}.items-head h3{font-size:13px}.item-row{display:grid;grid-template-columns:2fr 1fr 1fr 1fr auto;gap:8px;align-items:end;padding:9px 0;border-bottom:1px solid #edf1f5}.item-row select{width:100%}
@media(max-width:1000px){.pricing-hero,.directory-head{align-items:flex-start;flex-direction:column}.filters{justify-content:flex-start}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.search input{width:160px}}
@media(max-width:640px){.pricing-page{gap:13px}.stats{grid-template-columns:1fr 1fr}.directory{padding:11px}.form-grid{grid-template-columns:1fr}.form-grid .wide{grid-column:auto}.item-row{grid-template-columns:1fr 1fr}.item-row label:first-child{grid-column:1/-1}.head-actions{width:100%}.head-actions .btn{flex:1}.pricing-title{gap:10px}.pricing-title-icon{width:40px;height:40px;flex-basis:40px}.pricing-title p{max-width:100%}}
</style>
